(()=>{"use strict";function preparePlayer(player){if(player.hasAttribute("data-onegospel-ready")){return;}const audio=player.querySelector("audio[data-onegospel-audio]");const button=player.querySelector("[data-onegospel-toggle]");const label=player.querySelector("[data-onegospel-label]");const status=player.querySelector("[data-onegospel-status]");if(!audio||!button||!label||!status){return;}const source=audio.getAttribute("src")?.trim();if(!source){status.textContent="Adicione o endereço do áudio.";return;}const live=player.hasAttribute("data-onegospel-live");const playLabel=live?"Ouvir ao vivo":"Ouvir amostra";const stopLabel=live?"Parar":"Pausar";const stoppedMessage=live?"Transmissão parada.":"Reprodução pausada.";let playbackRequest=0;function showState(state,message){const active=state==="loading"||state==="playing";player.setAttribute("data-onegospel-state",state);label.textContent=active?stopLabel:playLabel;if(status.textContent!==message){status.textContent=message;}}function showError(){showState("error","Falha ao carregar o áudio. Tente novamente.");}audio.addEventListener("playing",()=>{if(!audio.paused){showState("playing",live?"Reproduzindo ao vivo.":"Reproduzindo a amostra.");}});audio.addEventListener("waiting",()=>{if(!audio.paused){showState("loading","Carregando áudio…");}});audio.addEventListener("pause",()=>{if(audio.paused&&!audio.ended&&!audio.error){showState("idle",stoppedMessage);}});audio.addEventListener("ended",()=>{showState("idle",live?"A transmissão terminou.":"Amostra concluída.");});audio.addEventListener("error",()=>{if(audio.error){showError();}});button.addEventListener("click",async()=>{const request=++playbackRequest;if(!audio.paused){audio.pause();if(live){audio.removeAttribute("src");audio.load();}showState("idle",stoppedMessage);return;}if(audio.getAttribute("src")!==source){audio.setAttribute("src",source);}else if(audio.error){audio.load();}showState("loading","Conectando ao áudio…");try{await audio.play();}catch(error){if(request===playbackRequest&&error.name!=="AbortError"){showError();}}});player.setAttribute("data-onegospel-ready","");audio.controls=false;audio.hidden=true;button.hidden=false;showState("idle",live?"Pronto para ouvir.":"Pronto para testar.");}function preparePage(){document.querySelectorAll("[data-onegospel-player]").forEach(preparePlayer);}if(document.readyState==="loading"){document.addEventListener("DOMContentLoaded",preparePage,{once:true});}else{preparePage();}})();
